13	// readBrainManifestFile decodes the canonical manifest without a byte ceiling.
14	// It uses the same checked descriptor as bounded state readers, without needing
15	// the source repository or Git. encoding/json buffers a whole JSON value and
16	// the manifest is materialized in memory: this is NOT a bounded-memory reader.
17	// Rewinding this descriptor (never reopening the path) preserves schema-first
18	// checks and tolerant reads versus strict rewrites, including unknown fields.
19	func readBrainManifestFile(brainDir string, tolerateUnknown bool) (*exportManifest, int, bool, bool, error) {
20		f, present, err := brainstore.OpenMemoryStateFileExpected(brainDir, exportManifestFileName, "brain manifest", nil)
21		if err != nil {
22			return nil, 0, false, present, fmt.Errorf("read brain manifest: %w", err)
23		}
24		if !present {
25			return &exportManifest{SchemaVersion: brainManifestSchemaVersion}, 0, false, false, nil
26		}
27		defer f.Close()
28		manifest, version, dropped, err := decodeBrainManifestFile(f, tolerateUnknown)
29		return manifest, version, dropped, true, err
30	}
31	
32	func decodeManifestPass(f *os.File, out any, strict bool) error {
33		if _, err := f.Seek(0, io.SeekStart); err != nil {
34			return err
35		}
36		decoder := json.NewDecoder(f)
37		if strict {
38			decoder.DisallowUnknownFields()
39		}
40		if err := decoder.Decode(out); err != nil {
41			return err
42		}
43		if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
44			return brainstore.ErrTrailingJSONData
45		}
46		return nil
47	}
48	
49	func decodeBrainManifestFile(f *os.File, tolerateUnknown bool) (*exportManifest, int, bool, error) {
50		var header struct {
51			SchemaVersion int `json:"schema_version"`
52		}
53		if err := decodeManifestPass(f, &header, false); err != nil {
54			return nil, 0, false, fmt.Errorf("parse brain manifest: %s: brain manifest cannot be parsed: %w", brainstore.StateCorruptCode, err)
55		}
56		version := header.SchemaVersion
57		if version > brainManifestSchemaVersion {
58			return nil, version, false, fmt.Errorf("%s: brain manifest schema version %d is newer than supported version %d; upgrade entire-brain to read it", brainstore.UnsupportedVersionCode, version, brainManifestSchemaVersion)
59		}
60		var manifest exportManifest
61		err := decodeManifestPass(f, &manifest, true)
62		dropped := false
63		if tolerateUnknown && brainstore.IsUnknownFieldError(err) {
64			manifest = exportManifest{}
65			err = decodeManifestPass(f, &manifest, false)
66			dropped = err == nil
67		}
68		if err != nil {
69			// An unknown field is not damage, and saying "cannot be parsed" sends
70			// the reader looking for corruption that is not there. The manifest is
71			// entirely readable; a WRITER is refusing it, because re-encoding from
72			// a struct that never saw the field would erase what another build
73			// recorded. Readers pass tolerateUnknown and are unaffected.
74			//
75			// Observed cost of the old wording: a component sat failed for four
76			// days reporting memory_state_corrupt, while the manifest was fine and
77			// the condition had already gone away.
78			//
79			// The error CODE stays memory_state_corrupt deliberately. It is part of
80			// the maintenance taxonomy with many consumers, so retyping this case
81			// is a contract change for a human to make, not a side effect of
82			// improving a sentence.
83			if !tolerateUnknown && brainstore.IsUnknownFieldError(err) {
84				return nil, version, false, fmt.Errorf(
85					"parse brain manifest: %s: brain manifest carries a field this build does not know (%w); "+
86						"the file is readable and is NOT damaged, but a writer will not rewrite it and silently drop that field. "+
87						"Use a build that knows the field, or let a read-only command run instead",
88					brainstore.StateCorruptCode, err)
89			}
90			return nil, version, false, fmt.Errorf("parse brain manifest: %s: brain manifest cannot be parsed: %w", brainstore.StateCorruptCode, err)
91		}
92		if version < brainManifestMinSchemaVersion {
93			return nil, version, false, fmt.Errorf("%s: brain manifest declares schema version %d, older than the first supported version %d", brainstore.UnsupportedVersionCode, version, brainManifestMinSchemaVersion)
94		}
95		normalizeBrainManifest(&manifest)
96		return &manifest, version, dropped, nil
97	}
