213	// readBrainManifest also reports whether it dropped fields written by another
214	// build, so status and doctor can recommend a refresh instead of staying silent.
215	func readBrainManifest(outputDir string, tolerateUnknownFields bool) (*exportManifest, bool, error) {
216		manifest, _, dropped, _, err := readBrainManifestFile(outputDir, tolerateUnknownFields)
217		return manifest, dropped, err
218	}
219	
220	// errManifestRoundTrips reports a manifest this build can already rewrite, so
221	// there is nothing for a forced refresh to discard.
222	var errManifestRoundTrips = errors.New("manifest round-trips")
223	
224	// discardManifestThisBuildCannotRewrite removes a manifest whose only defect is
225	// fields this build cannot name, so an explicit forced refresh can rebuild it.
226	//
227	// Every writer refuses such a manifest deliberately: re-encoding from a struct
228	// that never saw a field erases it. That leaves a brain readable but frozen,
229	// and until now the only way out was for a person to delete the file by hand.
230	// An operator asking for a forced refresh is asking for exactly that
231	// replacement, rebuilt from canonical sources -- but only for this one cause:
232	//
233	//   - a newer schema stays. Down-converting a vNext manifest is the loss the
234	//     version check exists to prevent, and --force does not overrule it.
235	//   - genuine corruption stays. That is a diagnosis for the operator, not bytes
236	//     to delete on a guess.
237	//
238	// The removal runs under the manifest write lock and through the checked
239	// remover, so it inherits the same symlink and file-identity guarantees as
240	// every other cooperative manifest mutation.
241	func discardManifestThisBuildCannotRewrite(brainDir string) (bool, error) {
242		unrewritable := false
243		err := brainstore.WithBrainManifestWriteLock(brainDir, func() error {
244			return removeCheckedMemoryStateFileValidated(brainDir, exportManifestFileName, "brain manifest", func(before os.FileInfo) (bool, error) {
245				f, present, err := brainstore.OpenMemoryStateFileExpected(brainDir, exportManifestFileName, "brain manifest", before)
246				if err != nil || !present {
247					return present, err
248				}
249				defer f.Close()
250				_, _, droppedUnknownFields, err := decodeBrainManifestFile(f, true)
251				if err != nil {
252					return true, err
253				}
254				if !droppedUnknownFields {
255					return true, errManifestRoundTrips
256				}
257				unrewritable = true
258				return true, nil
259			})
260		})
261		if errors.Is(err, errManifestRoundTrips) {
262			return false, nil
263		}
264		if err != nil {
265			return false, err
266		}
267		return unrewritable, nil
268	}
