405	func writeBrainManifestAndReadme(outputDir string, manifest exportManifest) error {
406		return brainstore.WithBrainManifestWriteLock(outputDir, func() error {
407			// All production manifest replacements share this leaf-specific lock and
408			// classify the exact present bytes while holding it. This does not claim
409			// to exclude hostile non-cooperating filesystem mutation, but no current
410			// writer can down-convert a vNext or erase unrecognized current bytes it
411			// observed.
412			if _, err := loadBrainManifestForReplace(outputDir); err != nil {
413				return err
414			}
415			normalizeBrainManifest(&manifest)
416			manifest.SchemaVersion = brainManifestSchemaVersion
417			data, err := json.MarshalIndent(manifest, "", "  ")
418			if err != nil {
419				return fmt.Errorf("encode %s: %w", exportManifestFileName, err)
420			}
421			data = append(data, '\n')
422			// Canonical manifest readers have no byte ceiling; retain every record
423			// and publish the complete document atomically.
424			if err := brainstore.WriteBrainRelativeFileAtomic(outputDir, exportManifestFileName, data, 0o600); err != nil {
425				return fmt.Errorf("write %s: %w", exportManifestFileName, err)
426			}
427			if err := brainstore.WriteBrainRelativeFileAtomic(outputDir, exportReadmeFileName, []byte(renderBrainReadme(manifest)), 0o600); err != nil {
428				return fmt.Errorf("write brain readme: %w", err)
429			}
430			return nil
431		})
432	}
433	
434	func renderBrainReadme(manifest exportManifest) string {
435		if manifest.Sources == nil || (manifest.Sources.Seed == nil && manifest.Sources.Semantic == nil && manifest.Sources.History == nil) {
436			return renderExportReadme(manifest)
437		}
438		return renderCombinedBrainReadme(manifest)
439	}
